-- Constraint necessária para o ON CONFLICT (claim) funcionar em fact_checks.
alter table public.fact_checks add constraint fact_checks_claim_key unique (claim);

-- Expansão: novas táticas de golpe (scam_patterns)
on conflict (id) do update set label = excluded.label, description = excluded.description, severity = excluded.severity, category = excluded.category, keywords = excluded.keywords, updated_at = now();

-- Expansão: novos domínios oficiais (known_domains)
on conflict (domain) do update set category = excluded.category;

-- Expansão: novas alegações verificadas (fact_checks)
on conflict (claim) do update set classification = excluded.classification, explanation = excluded.explanation, red_flags = excluded.red_flags, how_to_verify = excluded.how_to_verify, source_title = excluded.source_title, source_url = excluded.source_url, source_type = excluded.source_type, source_date = excluded.source_date, updated_at = now();
