insert into public.scam_patterns (id, label, description, severity, category, keywords) values
  ('golpe_pix_agendado', 'Falso Pix agendado', 'O golpista mostra um comprovante de Pix agendado e tenta convencer a vítima de que o pagamento já foi realizado. O agendamento pode ser cancelado antes da transferência, deixando o vendedor sem receber.', 'alto', 'financeiro', ARRAY['pix agendado', 'pagamento agendado', 'comprovante de agendamento', 'ja fiz o pix', 'o pix vai cair', 'ta programado']::text[]),
  ('golpe_falso_comprovante_pix', 'Falso comprovante de Pix', 'O criminoso envia uma imagem ou comprovante falsificado para fazer parecer que pagou por um produto ou serviço. A vítima é induzida a entregar a mercadoria antes de conferir o crédito no extrato.', 'alto', 'financeiro', ARRAY['comprovante do pix', 'comprovante de pagamento', 'pix realizado', 'pagamento realizado', 'ja paguei', 'confere ai o comprovante']::text[]),
  ('golpe_acesso_remoto_app', 'Golpe do acesso remoto', 'O criminoso se passa por funcionário de banco e afirma que existe uma irregularidade na conta. Depois pede para a vítima instalar um aplicativo que permite controlar ou acessar o celular.', 'alto', 'canal_e_link', ARRAY['instale o aplicativo', 'instalar um app', 'aplicativo de seguran[cç]a', 'acesso remoto', 'controle remoto', 'resolver o problema da conta']::text[]),
  ('golpe_falsa_taxa_encomenda', 'Falsa taxa para liberar encomenda', 'A vítima recebe uma mensagem dizendo que uma encomenda está retida ou atrasada e precisa pagar uma taxa para ser liberada. O golpe normalmente leva a uma página falsa que coleta dados e dinheiro.', 'alto', 'contexto_especifico', ARRAY['encomenda est[aá] retida', 'taxa de libera[cç][aã]o', 'taxa de entrega', 'regularizar sua encomenda', 'objeto retido', 'pagar para liberar']::text[]),
  ('golpe_falso_sac_0800', 'Falso SAC por número 0800', 'Criminosos podem disponibilizar números falsos de atendimento, inclusive em adesivos colocados próximos a caixas eletrônicos. A vítima acredita estar ligando para o banco e acaba entregando dados ou informações de segurança ao golpista.', 'alto', 'canal_e_link', ARRAY['n[uú]mero 0800', 'ligue para o suporte', 'central de atendimento', 'sac do banco', 'n[uú]mero de atendimento', 'ligue neste n[uú]mero']::text[]),
  ('golpe_deepfake_indenizacao', 'Deepfake de indenização', 'Vídeos manipulados usam a imagem ou a voz de apresentadores, advogados ou figuras conhecidas para anunciar falsas indenizações. O usuário é direcionado a um site falso para informar dados pessoais ou pagar valores.', 'alto', 'identidade_falsa', ARRAY['indeniza[cç][aã]o de', 'voc[eê] tem direito', 'saque sua indeniza[cç][aã]o', 'clique em saiba mais', 'receba seu dinheiro', 'sete sal[aá]rios m[ií]nimos']::text[]),
  ('golpe_falso_saque_receita', 'Falso saldo para saque da Receita', 'Anúncios falsos usam o nome da Receita Federal para afirmar que a pessoa possui um saldo ou dinheiro disponível para saque. O objetivo é levar a vítima a clicar em um link e entregar dados ou dinheiro.', 'alto', 'identidade_falsa', ARRAY['saldo para retirar', 'saque pelo cpf', 'valor liberado pelo cpf', 'consulte seu saldo', 'dinheiro dispon[ií]vel para saque', 'receita federal liberou']::text[]),
  ('golpe_falso_leilao_receita', 'Falso leilão da Receita', 'Golpistas anunciam falsos leilões de produtos atribuídos à Receita Federal e direcionam a vítima para sites fraudulentos. O conteúdo usa a identidade visual de órgãos públicos para criar aparência de legitimidade.', 'alto', 'identidade_falsa', ARRAY['leil[aã]o da receita', 'leil[aã]o oficial', 'encomendas apreendidas', 'celulares apreendidos', 'produtos abandonados', 'participe do leil[aã]o']::text[]),
  ('golpe_limite_credito_falso', 'Falso aumento de limite', 'Anúncios prometem aumento imediato de limite de crédito em um banco conhecido e levam a uma página que imita a identidade visual da instituição. O objetivo é capturar dados pessoais ou induzir outras ações fraudulentas.', 'alto', 'financeiro', ARRAY['aumentamos seu limite', 'novo limite de', 'limite total de \d+[.,]?\d*', 'ajuste seu novo limite', 'libere seu limite', 'limite aprovado']::text[]),
  ('deepfake_famoso', 'Deepfake de Famoso ou Jornalista', 'Uso de inteligência artificial para clonar imagem e voz de personalidades ou jornalistas simulando reportagens sobre investimentos com retornos garantidos.', 'alto', 'pressao_psicologica', ARRAY['deepfake', 'v[ií]deo manipulado', 'voz clonada', 'falso investimento', 'mat[eé]ria da tv', 'esc[aã]ndalo', 'roda viva']::text[]),
  ('falsa_prova_de_vida', 'Falsa Prova de Vida', 'Mensagem enviada em nome do INSS alegando suspensão do benefício por falta de prova de vida para capturar selfies e dados pessoais em sites falsos.', 'alto', 'pedido_de_dados_ou_dinheiro', ARRAY['prova de vida', 'inss', 'pend[eê]ncia', 'bloqueio de benef[ií]cio', 'reconhecimento facial', 'resolverfacil']::text[]),
  ('raspadinha_premiada', 'Falsa Raspadinha Digital', 'Página maliciosa que simula um jogo de raspadinha online com promessas de prêmios em dinheiro via Pix em nome de grandes empresas.', 'medio', 'financeiro', ARRAY['raspadinha', 'raspou achou ganhou', 'pr[eê]mio via pix', 'ganhe na hora', 'sorteio']::text[]),
  ('falso_auxilio_emergencial', 'Falso Auxílio Governamental', 'Fraude que divulga programas sociais inexistentes exigindo pagamento de taxa de cadastro ou repasse de chaves Pix.', 'alto', 'contexto_especifico', ARRAY['aux[ií]lio reconstru[çc][aã]o', 'libera[çc][aã]o do aux[ií]lio', 'saque emergencial', 'cadastro social']::text[]),
  ('falsa_portabilidade', 'Falsa Portabilidade de Consignado', 'Falsos correspondentes bancários oferecem redução de juros em empréstimos consignados para efetuar refinanciamentos não autorizados.', 'alto', 'financeiro', ARRAY['portabilidade consignado', 'redu[çc][aã]o de juros', 'troco consignado', 'refinanciamento']::text[]),
  ('golpe_pix_errado_devolucao', 'Pix errado com pedido de devolução', 'O golpista envia um Pix para a vítima e pede que o valor seja devolvido para uma chave diferente da conta de origem. Depois, também tenta contestar a transferência original para receber o dinheiro duas vezes.', 'alto', 'financeiro', ARRAY['fiz um pix errado', 'devolv[ae] para (esta|essa|outra) chave', 'manda de volta por pix', 'pix caiu por engano', 'devolu[cç][aã]o para outra conta']::text[]),
  ('golpe_troca_de_cartao', 'Troca de cartão durante pagamento', 'O criminoso observa a senha digitada e troca o cartão da vítima por outro parecido durante um pagamento. Em seguida, utiliza o cartão verdadeiro para realizar compras ou saques.', 'alto', 'contexto_especifico', ARRAY['seu cart[aã]o n[aã]o passou', 'insira o cart[aã]o novamente', 'digite a senha outra vez', 'vou limpar o chip', 'trocar a maquininha']::text[]),
  ('golpe_falso_concurso_publico', 'Falso concurso público', 'Anúncios falsos usam o nome de órgãos públicos para oferecer vagas, inscrições ou editais inexistentes. A vítima é induzida a fornecer documentos ou pagar uma falsa taxa de inscrição.', 'alto', 'contexto_especifico', ARRAY['inscri[cç][oõ]es abertas para concurso', 'pague a taxa de inscri[cç][aã]o', 'vagas imediatas no (ibama|governo|minist[ée]rio)', 'edital exclusivo', 'garanta sua vaga hoje', 'envie seus documentos para inscri[cç][aã]o']::text[]),
  ('golpe_falso_agendamento_documento', 'Falso agendamento de documento', 'Sites falsos imitam serviços de emissão de documentos e cobram antecipadamente por um agendamento que seria gratuito. A cobrança costuma ser apresentada no final do formulário, geralmente por Pix.', 'alto', 'contexto_especifico', ARRAY['taxa para agendar', 'pagamento para confirmar o agendamento', 'emiss[aã]o da (identidade|cin|rg)', 'agendamento confirmado ap[oó]s o pix', 'pague agora para reservar o hor[aá]rio']::text[]),
  ('golpe_falsa_doacao_online', 'Falsa campanha de doação', 'Criminosos reutilizam imagens de pessoas doentes, vídeos manipulados ou histórias inventadas para pedir doações. O dinheiro enviado por Pix não chega à pessoa apresentada na campanha.', 'alto', 'contexto_especifico', ARRAY['ajude (esta|essa) crian[cç]a', 'cada minuto conta', 'fa[cç]a sua doa[cç][aã]o', 'pix para salvar uma vida', 'meta de doa[cç][oõ]es', 'campanha solid[aá]ria urgente']::text[]),
  ('golpe_falso_leilao_publico', 'Falso leilão de veículos', 'Páginas falsas usam nomes e símbolos de órgãos públicos para anunciar veículos em leilões inexistentes. O interessado é pressionado a pagar sinal, taxa ou o valor do suposto lote.', 'alto', 'contexto_especifico', ARRAY['leil[aã]o oficial do detran', 've[ií]culo com at[ée] \d+% de desconto', 'pague o sinal do lote', 'lote reservado por poucos minutos', 'taxa de arremata[cç][aã]o', 'confirme o lance por pix']::text[]),
  ('golpe_falsa_inscricao_enem', 'Falsa inscrição no Enem', 'Sites não oficiais imitam a Página do Participante e solicitam CPF, outros dados pessoais e pagamento por Pix ou boleto. O pagamento não gera uma inscrição válida no exame.', 'alto', 'contexto_especifico', ARRAY['inscri[cç][aã]o enem 20\d{2}', 'confirme sua inscri[cç][aã]o por pix', 'pague a taxa do enem', 'vaga garantida no enem', 'p[aá]gina do participante']::text[]),
  ('golpe_falsa_regularizacao_cpf', 'Falsa regularização de CPF', 'Mensagens usam nome, CPF, símbolos da Receita Federal e ameaças de bloqueio para levar a vítima a um site falso. A página cobra por Pix uma suposta taxa para regularizar o documento.', 'alto', 'contexto_especifico', ARRAY['irregularidade fiscal grave', 'seu cpf ser[aá] bloqueado', 'regularize seu cpf', 'pend[êe]ncia grave em aberto', '[uú]ltimo aviso da receita', 'bloqueio (definitivo|imediato) do cpf']::text[]),
  ('golpe_falsa_pre_venda', 'Falsa pré-venda de produto', 'Anúncios oferecem antecipadamente produtos muito aguardados, mas direcionam a páginas que imitam a loja oficial. A vítima fornece dados pessoais e paga por um item que não está em pré-venda naquele canal.', 'alto', 'contexto_especifico', ARRAY['pr[ée]-venda exclusiva', 'seja um dos primeiros', '[aá]lbum oficial j[aá] dispon[ií]vel', 'compre antes do lan[cç]amento', 'oferta de pr[ée]-lan[cç]amento', 'reserva confirmada por pix']::text[]),
  ('golpe_promocao_relampago_falsa', 'Promoção relâmpago em site falso', 'Uma página imita uma loja conhecida, oferece produtos por valores muito baixos e pressiona o visitante com estoque limitado ou cronômetro. O pagamento é enviado a terceiros e o produto não é entregue.', 'alto', 'contexto_especifico', ARRAY['promo[cç][aã]o rel[âa]mpago', 'estoque limitado', '[uú]ltimas unidades', 'oferta termina em \d+ minutos', 'brinde gr[aá]tis na compra']::text[])
