insert into public.fact_checks (claim, classification, explanation, red_flags, how_to_verify, source_title, source_url, source_type, source_date) values
  ('O governo federal vai pagar um benefício extra de R$ 1.150 para aposentados e pensionistas do INSS.', 'provavelmente_falsa', 'A alegação foi desmentida pelo INSS e pelo Ministério da Previdência Social. A checagem identificou um vídeo manipulado com deepfake de uma apresentadora e um trecho antigo de televisão usado para dar aparência de veracidade ao falso anúncio.', ARRAY['Promessa de dinheiro inesperado', 'Valor fixo e elevado', 'Vídeo manipulado', 'Uso de apresentadora para dar credibilidade']::text[], ARRAY['Consulte o site oficial do INSS em gov.br/inss', 'Procure o benefício nos canais oficiais do governo', 'Desconfie de anúncios que pedem clique ou cadastro para liberar dinheiro']::text[], 'Aos Fatos', 'https://www.aosfatos.org/noticias/e-falso-que-governo-federal-vai-pagar-beneficio-extra-de-r-1150-a-beneficiarios-do-inss/', 'fact_checking', '19 de novembro de 2025'),
  ('Existe uma lista oficial de beneficiários do INSS que já foi liberada para receber a restituição de descontos indevidos.', 'provavelmente_falsa', 'A alegação foi classificada como golpe. O governo não havia divulgado uma lista pública desse tipo e os criminosos direcionavam usuários para uma página falsa que imitava o portal gov.br para obter dados e dinheiro.', ARRAY['Suposta lista de beneficiários', 'Uso de página que imita gov.br', 'Promessa de restituição', 'Anúncio patrocinado']::text[], ARRAY['Consulte informações diretamente no Meu INSS', 'Acesse gov.br pelo endereço digitado manualmente', 'Não informe CPF em páginas acessadas por anúncios suspeitos']::text[], 'Aos Fatos', 'https://www.aosfatos.org/noticias/e-golpe-lista-de-beneficiarios-que-vao-receber-restituicao-de-descontos-do-inss/', 'fact_checking', '15 de maio de 2025'),
  ('A Receita Federal liberou R$ 30.450,90 para saque pelo CPF de usuários das redes sociais.', 'provavelmente_falsa', 'A Receita Federal informou que não havia consulta para liberação de saques vinculados ao CPF. A publicação levava a uma página fraudulenta e utilizava o nome da Receita para induzir vítimas a fornecer informações.', ARRAY['Valor inesperado disponível', 'Uso do CPF como suposta chave de consulta', 'Link para saque', 'Uso indevido da Receita Federal']::text[], ARRAY['Consulte informações somente em gov.br/receitafederal', 'Não clique em links enviados por anúncios ou mensagens suspeitas', 'Verifique se o endereço termina em gov.br']::text[], 'Agência Lupa', 'https://www.agencialupa.org/jornalismo/2025/01/16/e-golpe-post-de-saque-de-r-30-mil-atribuido-a-receita-federal/', 'fact_checking', '16 de janeiro de 2025'),
  ('Um e-mail da Receita Federal informa que existe uma pendência grave no CPF que pode bloquear contas bancárias, documentos e viagens.', 'provavelmente_falsa', 'A mensagem foi identificada como golpe. O conteúdo usava ameaças e urgência para fazer a vítima clicar em um link que levava a uma página semelhante ao portal do governo.', ARRAY['Ameaça de bloqueio', 'Sensação de urgência', 'Link em e-mail', 'Página imitando o governo']::text[], ARRAY['Consulte seu CPF diretamente no site oficial da Receita', 'Não use o link recebido no e-mail', 'Desconfie de ameaças que exigem regularização imediata']::text[], 'Agência Lupa', 'https://www.agencialupa.org/jornalismo/2025/03/11/e-golpe-e-mail-atribuido-a-receita-federal-sobre-pendencia-no-cpf/', 'fact_checking', '11 de março de 2025'),
  ('É preciso pagar uma taxa para liberar uma encomenda retida pelos Correios após atraso na entrega.', 'provavelmente_falsa', 'A publicação foi identificada como golpe. O link não tinha relação com os Correios e direcionava para uma página fraudulenta que solicitava dados pessoais e pagamento para uma falsa liberação.', ARRAY['Encomenda retida', 'Cobrança inesperada', 'Link fora do canal oficial', 'Pagamento para liberar entrega']::text[], ARRAY['Consulte o rastreamento diretamente em correios.com.br', 'Não pague taxas por links recebidos em mensagens suspeitas', 'Confira o domínio antes de informar qualquer dado']::text[], 'Agência Lupa', 'https://www.agencialupa.org/jornalismo/2025/01/29/golpe-de-falsa-taxa-dos-correios-volta-a-circular-nas-redes/', 'fact_checking', '29 de janeiro de 2025'),
  ('Consumidores que usaram o Nubank têm direito a uma indenização de até R$ 10 mil.', 'provavelmente_falsa', 'A alegação foi desmentida e fazia parte de uma fraude. Vídeos manipulados com deepfake eram usados para divulgar uma suposta indenização inexistente e levar usuários a um site falso para fornecer dados pessoais.', ARRAY['Promessa de indenização', 'Valor alto e inesperado', 'Vídeo manipulado', 'Site falso para consulta']::text[], ARRAY['Consulte informações no aplicativo ou site oficial do Nubank', 'Não informe CPF em páginas abertas por anúncios suspeitos', 'Procure confirmação em fontes independentes e oficiais']::text[], 'Agência Lupa', 'https://www.agencialupa.org/jornalismo/2025/04/11/e-falso-que-nubank-esta-oferecendo-indenizacao-de-r-10-mil-para-clientes/', 'fact_checking', '11 de abril de 2025'),
  ('O Nubank aumentou o limite de crédito de usuários para R$ 6.100 por meio de uma promoção divulgada nas redes sociais.', 'provavelmente_falsa', 'A alegação fazia parte de um golpe. O anúncio levava para um site que não tinha relação com o Nubank e usava elementos visuais da marca para parecer legítimo.', ARRAY['Aumento automático de limite', 'Valor específico prometido', 'Site fora do domínio oficial', 'Uso de identidade visual da empresa']::text[], ARRAY['Confira seu limite apenas no aplicativo ou site oficial', 'Não use links patrocinados para validar uma suposta oferta bancária', 'Confirme o domínio antes de fornecer dados']::text[], 'Agência Lupa', 'https://www.agencialupa.org/jornalismo/2025/06/13/aumento-de-limite-de-credito-para-r-6.100-00-e-golpe-site-usa-identidade-visual-do-nubank/', 'fact_checking', '13 de junho de 2025'),
  ('A Caixa oferece uma consulta para descobrir se a pessoa tem direito a uma indenização da Receita Federal.', 'provavelmente_falsa', 'A publicação levava para um site falso que imitava a Caixa. A instituição não oferecia a consulta anunciada e a página fraudulenta tentava obter dados pessoais.', ARRAY['Consulta de indenização', 'Pedido de CPF', 'Site que imita banco', 'Promessa de dinheiro']::text[], ARRAY['Digite caixa.gov.br manualmente no navegador', 'Não informe dados pessoais em páginas de anúncios', 'Compare o endereço do site com o domínio oficial']::text[], 'Agência Lupa', 'https://www.agencialupa.org/jornalismo/2025/05/30/e-golpe-site-da-caixa-que-simula-consulta-de-indenizacao-da-receita/', 'fact_checking', '30 de maio de 2025'),
  ('Os Correios estão oferecendo vagas com salário de R$ 3.900 e cadastro 100% online nas redes sociais.', 'provavelmente_falsa', 'Os Correios alertaram que anúncios desse tipo utilizavam indevidamente a marca da empresa e do governo. As contratações da empresa são feitas por concurso público com editais divulgados pelos canais oficiais.', ARRAY['Vaga sem experiência', 'Cadastro totalmente online', 'Uso da marca dos Correios', 'Possível cobrança de taxa']::text[], ARRAY['Consulte oportunidades diretamente em correios.com.br', 'Procure o edital oficial do concurso', 'Não pague taxas para links recebidos em anúncios suspeitos']::text[], 'Agência Lupa', 'https://www.agencialupa.org/jornalismo/2025/09/01/e-golpe-anuncio-de-vagas-nos-correios-com-salario-de-r-3-900/', 'fact_checking', '1 de setembro de 2025'),
  ('A Receita Federal abriu um leilão oficial de smartphones provenientes de encomendas abandonadas, esquecidas ou confiscadas.', 'provavelmente_falsa', 'A publicação foi identificada como golpe e levava para um site falso de compras. O anúncio usava o nome da Receita Federal para criar aparência de legitimidade.', ARRAY['Oferta de produtos muito baratos', 'Suposto leilão oficial', 'Uso da marca Receita Federal', 'Link externo']::text[], ARRAY['Consulte leilões diretamente nos canais oficiais da Receita', 'Não faça pagamentos em sites enviados por anúncios suspeitos', 'Verifique o domínio antes de continuar']::text[], 'Agência Lupa', 'https://www.agencialupa.org/jornalismo/2025/01/21/golpe-no-facebook-usa-falso-leilao-da-receita-para-enganar-usuarios/', 'fact_checking', '21 de janeiro de 2025'),
  ('O Mercado Livre está oferecendo celulares, eletrodomésticos e outros produtos com 95% de desconto após uma pesquisa e uma roleta promocional.', 'provavelmente_falsa', 'A campanha não existia. A checagem mostrou que a promoção direcionava usuários para páginas falsas que imitavam o Mercado Livre e o Mercado Pago, coletando dados e dinheiro.', ARRAY['Desconto extremo', 'Questionário com prêmio', 'Roleta promocional', 'Página falsa de pagamento']::text[], ARRAY['Verifique promoções diretamente no mercadolivre.com.br', 'Evite questionários promocionais acessados por anúncios desconhecidos', 'Confirme a URL antes de pagar']::text[], 'Aos Fatos', 'https://www.aosfatos.org/noticias/golpe-mercado-livre-desconto-celulares-geladeiras/', 'fact_checking', '4 de dezembro de 2024'),
  ('A vacina contra a dengue faz parte de um experimento mortal e não seria segura.', 'provavelmente_falsa', 'A alegação foi classificada como falsa. A checagem informou que os imunizantes contra dengue foram aprovados pela Anvisa e que não existem evidências de que façam parte de um experimento mortal.', ARRAY['Linguagem alarmista', 'Afirmação sem evidência', 'Vídeo viral', 'Ataque genérico à segurança da vacina']::text[], ARRAY['Consulte informações sobre vacinas no site da Anvisa', 'Confira orientações do Ministério da Saúde', 'Procure estudos e fontes médicas reconhecidas']::text[], 'Agência Lupa', 'https://www.agencialupa.org/jornalismo/2025/06/10/e-falso-que-a-vacina-da-dengue-seja-parte-de-um-experimento-letal/', 'fact_checking', '10 de junho de 2025'),
  ('Vacinas contra dengue e gripe contêm grafeno e substâncias fluorescentes.', 'provavelmente_falsa', 'A alegação foi desmentida. O Ministério da Saúde informou que não há vacina aprovada pela OMS com grafeno como componente ativo e a fabricante da vacina contra dengue informou que o produto não contém grafeno ou óxido de grafeno.', ARRAY['Alegação sobre substância secreta', 'Uso de microscopia como suposta prova', 'Ausência de documentação regulatória', 'Linguagem alarmista']::text[], ARRAY['Consulte a bula aprovada pela Anvisa', 'Confira comunicados do Ministério da Saúde', 'Não trate vídeos de microscópio como prova isolada de composição química']::text[], 'Agência Lupa', 'https://www.agencialupa.org/jornalismo/2025/02/17/e-falso-que-vacinas-contra-dengue-e-gripe-sejam-contaminadas-com-grafeno/', 'fact_checking', '17 de fevereiro de 2025'),
  ('Tomar caldo de cana, água de coco e uma fórmula manipulada com Eupatorium e Phosphorus cura ou previne a dengue.', 'provavelmente_falsa', 'Não existe comprovação científica de que essas bebidas ou a fórmula mencionada curem ou previnam a dengue. A checagem destacou limitações metodológicas dos estudos citados e recomendou seguir o manejo clínico adequado.', ARRAY['Promessa de cura rápida', 'Uso de receita caseira', 'Ausência de evidência clínica robusta', 'Promessa de imunidade']::text[], ARRAY['Consulte orientações do Ministério da Saúde', 'Procure atendimento de saúde para sintomas de dengue', 'Desconfie de receitas que prometem cura ou imunidade']::text[], 'Agência Lupa', 'https://www.agencialupa.org/jornalismo/2025/02/14/caldo-de-cana-agua-de-coco-e-formulas-manipuladas-nao-curam-a-dengue/', 'fact_checking', '14 de fevereiro de 2025'),
  ('Beber três litros de água alcalina por dia cura a dengue em 72 horas.', 'provavelmente_falsa', 'A alegação foi classificada como falsa. Não há evidências científicas de que a ingestão de água alcalina cure a dengue ou elimine o vírus em 72 horas.', ARRAY['Promessa de cura em prazo curto', 'Explicação pseudocientífica', 'Recomendação de tratamento caseiro', 'Ausência de evidência clínica']::text[], ARRAY['Consulte informações de saúde em fontes oficiais', 'Não substitua tratamento médico por receitas virais', 'Procure orientação profissional em caso de sintomas']::text[], 'Agência Lupa', 'https://www.agencialupa.org/jornalismo/2025/08/15/beber-agua-alcalina-nao-cura-a-dengue/', 'fact_checking', '15 de agosto de 2025'),
  ('Uma bebida feita com limão, maçã, couve, alho e mel previne ou elimina a dengue.', 'provavelmente_falsa', 'A checagem concluiu que não existe comprovação científica de que a receita tenha eficácia contra a dengue. A orientação oficial é seguir o manejo clínico da doença e evitar automedicação ou receitas milagrosas.', ARRAY['Receita milagrosa', 'Promessa de prevenção', 'Promessa de eliminar a doença', 'Ausência de evidência científica']::text[], ARRAY['Consulte recomendações do Ministério da Saúde', 'Não use receitas virais como substitutas do tratamento', 'Confira se a alegação aparece em fontes médicas reconhecidas']::text[], 'Agência Lupa', 'https://www.agencialupa.org/jornalismo/2025/05/08/bebida-com-limao-maca-couve-alho-e-mel-nao-previne-ou-cura-a-dengue/', 'fact_checking', '8 de maio de 2025'),
  ('Bill Gates inaugurou uma biofábrica de mosquitos em Curitiba e o episódio estaria ligado a um alerta global da OMS sobre vírus transmitidos por mosquitos.', 'provavelmente_falsa', 'A alegação foi desmentida. A biofábrica em Curitiba foi viabilizada pelo Governo do Paraná e pela Fiocruz, e o alerta da OMS citado na publicação não estabelecia relação com Bill Gates ou com a unidade brasileira.', ARRAY['Associação de acontecimentos sem evidência', 'Uso de figura pública para gerar suspeita', 'Interpretação conspiratória', 'Ausência de conexão documental']::text[], ARRAY['Leia comunicados oficiais da Fiocruz e do Governo do Paraná', 'Confira o conteúdo original do alerta da OMS', 'Compare a data e o contexto dos dois acontecimentos']::text[], 'Agência Lupa', 'https://www.agencialupa.org/jornalismo/2025/07/29/bill-gates-nao-inaugurou-biofabrica-de-mosquitos-em-curitiba/', 'fact_checking', '29 de julho de 2025'),
  ('Estão dizendo que o INSS envia servidores às casas dos segurados para fazer prova de vida, revisar benefícios ou recolher dados.', 'provavelmente_falsa', 'O INSS informou que não envia servidores sem aviso prévio às residências para pedir senhas, documentos, dados pessoais ou informações bancárias. Atendimentos domiciliares específicos precisam ser previamente autorizados e comunicados ao cidadão.', ARRAY['Visita sem agendamento', 'Pedido de senha ou documento', 'Uso de crachá como única prova', 'Solicitação de pagamento']::text[], ARRAY['Consulte o Meu INSS', 'Ligue para a Central 135', 'Não permita a entrada de visitante não agendado']::text[], 'Instituto Nacional do Seguro Social', 'https://www.gov.br/inss/pt-br/assuntos/e-golpe-inss-nao-vai-a-casa-dos-segurados-para-pedir-dados', 'oficial', '22 de abril de 2026'),
  ('Estão dizendo que a alíquota previdenciária paga pelo MEI aumentou em 2025.', 'provavelmente_falsa', 'O INSS esclareceu que a alíquota do MEI continuou em 5% do salário mínimo. O valor do DAS aumentou porque o salário mínimo foi reajustado, e não porque o percentual da contribuição mudou.', ARRAY['Confusão entre valor e percentual', 'Ausência de referência ao salário mínimo', 'Mensagem sem fonte oficial']::text[], ARRAY['Consulte o Portal do Simples Nacional', 'Confira o valor no aplicativo oficial MEI', 'Leia os comunicados do INSS']::text[], 'Instituto Nacional do Seguro Social', 'https://www.gov.br/inss/pt-br/noticias/e-falsa-a-informacao-que-aliquota-de-contribuicao-do-mei-subiu', 'oficial', '26 de fevereiro de 2025'),
  ('Estão anunciando vagas de agente de saúde com salário de até R$ 5 mil e cobrando uma taxa de inscrição.', 'provavelmente_falsa', 'O anúncio analisado imitava páginas do governo e solicitava dados pessoais e pagamento por Pix. O Ministério da Saúde informou que os cursos do Programa Mais Saúde com Agente são gratuitos e que não havia inscrições abertas para aquela oferta.', ARRAY['Cobrança por Pix', 'Promessa de contratação', 'Site que imita o governo', 'Prazo prestes a terminar']::text[], ARRAY['Consulte o portal do Ministério da Saúde', 'Não pague taxas recebidas por anúncio em rede social', 'Confira se o endereço termina em gov.br']::text[], 'g1 Fato ou Fake', 'https://g1.globo.com/fato-ou-fake/noticia/2025/05/30/e-fake-anuncio-no-instagram-que-promete-vagas-para-agente-de-saude-e-salario-de-ate-r-5-mil-trata-se-de-golpe.ghtml', 'fact_checking', '30 de maio de 2025'),
  ('Estão dizendo que a vacina da dengue do Instituto Butantan foi aplicada como um experimento em cobaias humanas.', 'provavelmente_falsa', 'O Ministério da Saúde informou ao Fato ou Fake que a vacina passou pelas etapas de avaliação exigidas pelos órgãos reguladores antes de ser incorporada ao SUS. O monitoramento de eventos após a aplicação faz parte da farmacovigilância e não prova que a população tenha sido usada como cobaia.', ARRAY['Uso da palavra cobaia', 'Mensagem de pânico', 'Confusão entre monitoramento e experimento', 'Falta de documento regulatório']::text[], ARRAY['Consulte os comunicados da Anvisa', 'Verifique as informações do Ministério da Saúde', 'Procure o registro oficial do imunizante']::text[], 'g1 Fato ou Fake', 'https://g1.globo.com/fato-ou-fake/noticia/2026/06/19/e-fake-que-vacina-da-dengue-foi-aplicada-como-experimento-e-usou-populacao-como-cobaia.ghtml', 'fact_checking', '19 de junho de 2026'),
  ('Estão dizendo que consumir sal em excesso faz bem à saúde e não aumenta o risco de pressão alta.', 'provavelmente_falsa', 'Especialista consultado pelo Fato ou Fake explicou que o excesso de sal aumenta a chance de hipertensão e pode sobrecarregar o coração e os rins. A recomendação apresentada pela fonte é limitar o consumo de sal, e não aumentá-lo.', ARRAY['Contraria recomendações médicas consolidadas', 'Promessa ampla de benefício', 'Uso seletivo de estudos', 'Incentivo ao consumo excessivo']::text[], ARRAY['Consulte orientações do Ministério da Saúde', 'Converse com profissional de saúde', 'Verifique recomendações da Organização Mundial da Saúde']::text[], 'g1 Fato ou Fake', 'https://g1.globo.com/fato-ou-fake/noticia/2025/07/14/e-fake-que-consumo-de-sal-em-excesso-faz-bem-a-saude.ghtml', 'fact_checking', '14 de julho de 2025'),
  ('Estão dizendo que apertar a tecla 2 em uma ligação sobre vacinação bloqueia o celular e permite que golpistas façam Pix.', 'provavelmente_falsa', 'Especialista ouvido pelo Aos Fatos afirmou que apenas apertar uma tecla em uma ligação não permite a invasão descrita na corrente. Para obter acesso, normalmente seria necessária uma vulnerabilidade ou uma ação adicional, como instalar programa malicioso, abrir arquivo ou informar dados em página falsa.', ARRAY['Relato sem identificação da vítima', 'Invasão instantânea apenas ao apertar uma tecla', 'Número de telefone apresentado como prova', 'Pedido para encaminhar a todos']::text[], ARRAY['Não instale aplicativos enviados por desconhecidos', 'Verifique permissões concedidas ao celular', 'Consulte alertas de segurança de fontes especializadas']::text[], 'Aos Fatos', 'https://www.aosfatos.org/noticias/golpe-vacina-celular-invadido/', 'fact_checking', '6 de abril de 2026'),
  ('Uma campanha chamada Ajude a Manu está pedindo Pix para tratar uma criança com doença rara.', 'provavelmente_falsa', 'O Aos Fatos verificou que a campanha utilizava vídeos manipulados e imagens de pessoas que não correspondiam à história divulgada. O site imitava plataformas legítimas de arrecadação e direcionava os pagamentos para os golpistas.', ARRAY['Vídeo emocional sem identificação verificável', 'Imagens reutilizadas', 'Site que imita plataforma de doações', 'Pix fora de instituição conhecida']::text[], ARRAY['Faça busca reversa das imagens', 'Confirme a campanha diretamente com hospital ou família identificada', 'Verifique o domínio da plataforma de arrecadação']::text[], 'Aos Fatos', 'https://www.aosfatos.org/noticias/golpe-deepfakes-imagens-crianca-doente-para-roubar-dinheiro-de-doacoes/', 'fact_checking', '17 de abril de 2025'),
  ('Estão dizendo que a vacina trivalente contra a gripe contém cepa de Covid-19 e provoca gripe.', 'provavelmente_falsa', 'O Instituto Butantan esclareceu que a vacina trivalente não contém cepa do coronavírus e não causa gripe. O imunizante utiliza vírus inativados, incapazes de causar a doença nas pessoas vacinadas.', ARRAY['Mistura doenças diferentes', 'Afirmação sem composição do produto', 'Mensagem que desencoraja a vacinação', 'Ausência de fonte sanitária']::text[], ARRAY['Consulte a bula registrada', 'Verifique o portal do Instituto Butantan', 'Procure orientação em uma unidade de saúde']::text[], 'Secretaria da Saúde do Estado de São Paulo', 'https://saude.sp.gov.br/coordenadoria-de-controle-de-doencas/noticias/29042025-butantan-desmente-10-fake-news-sobre-a-vacina-trivalente-da-gripe', 'oficial', '29 de abril de 2025'),
  ('Estão oferecendo óculos de grau gratuitos em unidades de saúde de Araras.', 'provavelmente_falsa', 'A Prefeitura de Araras informou que a publicação era falsa e que as unidades mencionadas não estavam distribuindo óculos gratuitamente. A circulação do conteúdo fez pessoas procurarem os locais em busca do benefício inexistente.', ARRAY['Oferta local sem publicação oficial', 'Unidades específicas citadas sem contato', 'Mensagem compartilhada em redes sociais']::text[], ARRAY['Consulte o site da Prefeitura de Araras', 'Ligue diretamente para a unidade de saúde', 'Verifique os canais da Secretaria Municipal de Saúde']::text[], 'Prefeitura de Araras', 'https://araras.sp.gov.br/noticias/28402', 'oficial', '15 de setembro de 2025'),
  ('Um site que parece ser do Inep está fazendo inscrições para o Enem e cobrando por Pix ou boleto.', 'provavelmente_falsa', 'O Fato ou Fake verificou páginas que imitavam a inscrição oficial do Enem para roubar dados e gerar cobranças fraudulentas. O Centro Integrado de Segurança Cibernética do Governo Digital alertou que esses endereços simulavam inscrições que não existiam.', ARRAY['Domínio sem gov.br', 'Cobrança em página não oficial', 'Aparência copiada do Inep', 'Mensagem urgente sobre encerramento']::text[], ARRAY['Acesse a Página do Participante pelos canais do Inep', 'Confira se o domínio pertence ao gov.br', 'Não use links patrocinados sem verificar o endereço']::text[], 'g1 Fato ou Fake', 'https://g1.globo.com/fato-ou-fake/noticia/2026/06/10/e-fake-site-nao-oficial-que-imita-pagina-de-inscricao-do-enem-trata-se-de-golpe.ghtml', 'fact_checking', '10 de junho de 2026'),
  ('Estão anunciando a pré-venda do álbum da Copa do Mundo de 2026 e cobrando por Pix.', 'provavelmente_falsa', 'A Panini informou ao Fato ou Fake que não havia pré-venda oficial no período em que os anúncios circulavam. As páginas falsas imitavam a empresa, coletavam dados pessoais e direcionavam pagamentos a uma intermediadora.', ARRAY['Pré-venda antes do anúncio oficial', 'Domínio parecido com o da empresa', 'Cronômetro de oferta', 'Pagamento por Pix a terceiro']::text[], ARRAY['Consulte panini.com.br', 'Confira as redes oficiais da editora', 'Verifique o nome do recebedor antes de pagar']::text[], 'g1 Fato ou Fake', 'https://g1.globo.com/fato-ou-fake/noticia/2026/02/23/e-fake-anuncio-de-pre-venda-do-album-da-copa-do-mundo-2026-trata-se-de-golpe.ghtml', 'fact_checking', '23 de fevereiro de 2026'),
  ('A Receita Federal está enviando mensagens no WhatsApp com links para pagar dívidas e evitar o bloqueio do CPF.', 'provavelmente_falsa', 'A Receita Federal desmentiu as mensagens analisadas pelo Fato ou Fake. Elas usavam dados verdadeiros das vítimas, símbolos oficiais, ameaças de bloqueio e links que levavam a páginas falsas para cobrança por Pix.', ARRAY['Ameaça de bloqueio imediato', 'Link recebido por WhatsApp', 'Uso do CPF para gerar confiança', 'Cobrança por Pix']::text[], ARRAY['Consulte sua situação no e-CAC', 'Digite manualmente o endereço oficial da Receita', 'Não efetue pagamento por link recebido em mensagem']::text[], 'g1 Fato ou Fake', 'https://g1.globo.com/fato-ou-fake/noticia/2026/01/22/e-fake-mensagem-de-whatsapp-em-nome-da-receita-federal-com-link-para-pagamento-de-dividas-de-impostos-trata-se-de-golpe.ghtml', 'fact_checking', '22 de janeiro de 2026'),
  ('Uma mensagem da Receita Federal diz que existe uma pendência grave no Imposto de Renda e que o CPF será bloqueado amanhã.', 'provavelmente_falsa', 'A mensagem verificada pelo Fato ou Fake levava a uma página semelhante ao gov.br e apresentava uma falsa dívida. O site ameaçava bloquear CPF, contas, cartões e Pix para pressionar a vítima a pagar uma quantia por QR Code.', ARRAY['Prazo termina amanhã', 'Ameaça de bloqueio total', 'Falsa certidão fiscal', 'Desconto para pagamento imediato']::text[], ARRAY['Consulte diretamente o e-CAC', 'Confirme pendências no aplicativo oficial da Receita Federal', 'Verifique o destinatário do Pix']::text[], 'g1 Fato ou Fake', 'https://g1.globo.com/fato-ou-fake/noticia/2026/02/26/e-fake-mensagem-de-whatsapp-sobre-regularizacao-de-pendencia-grave-da-receita-federal-trata-se-de-golpe.ghtml', 'fact_checking', '26 de fevereiro de 2026'),
  ('Um site com a aparência da Shopee está oferecendo produtos em promoção relâmpago por preços muito baixos.', 'provavelmente_falsa', 'A Shopee confirmou ao Fato ou Fake que a página externa e as ofertas analisadas eram falsas. O site usava preços muito baixos, estoque limitado, mensagens de urgência e pagamento por Pix fora da plataforma.', ARRAY['Preço muito abaixo do mercado', 'Pagamento fora do aplicativo', 'Site sem CNPJ ou contato', 'Pressão por estoque limitado']::text[], ARRAY['Abra o aplicativo oficial da Shopee', 'Pesquise a oferta dentro da própria plataforma', 'Não pague Pix solicitado por página externa']::text[], 'g1 Fato ou Fake', 'https://g1.globo.com/fato-ou-fake/noticia/2025/11/27/e-fake-site-que-imita-pagina-da-shopee-e-oferece-promocao-relampago-trata-se-de-golpe.ghtml', 'fact_checking', '27 de novembro de 2025'),
  ('Mensagem avisa sobre Auxílio Reconstrução no valor de R$ 1.050 liberado via Pix mediante cadastro em site externo.', 'provavelmente_falsa', 'O Ministério da Integração e do Desenvolvimento Regional informou que não há programa com esses moldes. A mensagem em circulação no WhatsApp trata-se de um golpe para capturar dados pessoais e chaves Pix das vítimas.', ARRAY['Promessa de dinheiro via Pix', 'Cadastro em site externo', 'Nome de programa governamental não confirmado']::text[], ARRAY['Consulte o site oficial do Ministério da Integração e do Desenvolvimento Regional (gov.br)', 'Não cadastre dados em sites fora do domínio gov.br', 'Procure confirmação em veículos jornalísticos estabelecidos']::text[], 'g1 Fato ou Fake', 'https://g1.globo.com/fato-ou-fake/noticia/2026/06/17/e-fake-mensagem-que-imita-visual-do-ifood-e-oferece-link-de-raspadinha-da-copa-do-mundo-trata-se-de-golpe.ghtml', 'fact_checking', '20 de agosto de 2026'),
  ('SMS em nome do INSS avisa pendência na prova de vida com link resolverfacil.com para biometria facial.', 'provavelmente_falsa', 'O INSS esclareceu que não envia links de acesso por SMS e nem solicita reconhecimento facial fora do aplicativo Meu INSS. Páginas do domínio resolverfacil.com são fraudulentas e roubam dados e fotos do usuário.', ARRAY['Link fora do domínio gov.br', 'Pedido de biometria facial por SMS', 'Ameaça de bloqueio do benefício']::text[], ARRAY['Consulte a prova de vida apenas pelo app Meu INSS', 'Ligue para a Central 135', 'Não clique em links recebidos por SMS']::text[], 'g1 Fato ou Fake', 'https://g1.globo.com/fato-ou-fake/noticia/2026/06/10/e-fake-mensagem-em-nome-do-inss-que-avisa-sobre-pendencia-de-prova-de-vida-e-tem-link-para-reconhecimento-facial.ghtml', 'fact_checking', '10 de junho de 2026'),
  ('iFood lançou jogo de raspadinha online da Copa do Mundo com prêmios de até R$ 30.000 no Pix.', 'provavelmente_falsa', 'O iFood desmentiu a existência do concurso e alertou que o endereço eletrônico utilizado na mensagem é malicioso. A página buscava induzir o compartilhamento em massa para capturar dados cadastrais.', ARRAY['Prêmio alto e imediato via Pix', 'Pedido de compartilhamento em massa', 'Site que imita a marca iFood']::text[], ARRAY['Verifique promoções apenas no aplicativo oficial do iFood', 'Confira os canais oficiais da marca nas redes sociais', 'Não compartilhe links de promoções não confirmadas']::text[], 'g1 Fato ou Fake', 'https://g1.globo.com/fato-ou-fake/noticia/2026/06/17/e-fake-mensagem-que-imita-visual-do-ifood-e-oferece-link-de-raspadinha-da-copa-do-mundo-trata-se-de-golpe.ghtml', 'fact_checking', '17 de junho de 2026'),
  ('Youtuber Felca foi expulso por Vera Magalhães do Roda Viva após revelar aplicativo de investimento de R$ 22.000 ao mês.', 'provavelmente_falsa', 'O conteúdo veiculado em redes sociais é um anúncio golpista montado com auxílio de inteligência artificial. A TV Cultura e a jornalista Vera Magalhães negaram o fato e alertaram para a fraude de investimento.', ARRAY['Vídeo manipulado por IA', 'Promessa de retorno financeiro alto e fixo', 'Uso de figuras públicas sem autorização']::text[], ARRAY['Confira os canais oficiais da TV Cultura e do Roda Viva', 'Desconfie de vídeos que prometem ganhos financeiros extraordinários', 'Procure a notícia em veículos jornalísticos estabelecidos']::text[], 'Boatos.org', 'https://www.boatos.org/entretenimento/felca-e-expulso-por-vera-magalhaes-do-roda-viva-ao-falar-de-investimento-incrivel.html', 'fact_checking', '3 de setembro de 2026'),
  ('Palhaço Mauro de 70 anos vende apresentações gravadas na web para custear cirurgia cardíaca e sustentar a neta.', 'provavelmente_falsa', 'A história e os personagens foram fabricados por inteligência artificial. A narrativa apelativa é usada para atrair internautas a efetuarem pagamentos em plataformas não verificadas.', ARRAY['História emocional sem confirmação', 'Personagem fabricado por IA', 'Pedido de pagamento em plataforma não verificada']::text[], ARRAY['Faça busca reversa das imagens do perfil', 'Desconfie de histórias comoventes sem fonte verificável', 'Não pague por conteúdo em páginas recém-criadas']::text[], 'Boatos.org', 'https://www.boatos.org/brasil/palhaco-mauro-vende-apresentacao-online-para-custear-tratamento-do-coracao.html', 'fact_checking', '2 de setembro de 2026'),
  ('Vale, Havaianas e Sadia estão dando R$ 5.000 no Dia das Mães para quem preencher pesquisa no WhatsApp.', 'provavelmente_falsa', 'As empresas confirmaram que não veiculam campanhas com prêmios em dinheiro condicionadas ao repasse de links no WhatsApp. O objetivo das páginas falsas é disseminar anúncios maliciosos e roubar dados.', ARRAY['Pesquisa com prêmio em dinheiro', 'Pedido de repasse no WhatsApp', 'Uso de marcas conhecidas sem confirmação oficial']::text[], ARRAY['Confira as redes sociais oficiais das marcas citadas', 'Não preencha pesquisas recebidas por link de terceiros', 'Desconfie de prêmios condicionados a repasse em massa']::text[], 'Boatos.org', 'https://www.boatos.org/tecnologia/vale-supermercados-bh-sadia-e-havaianas-dao-presentes-no-dia-das-maes.html', 'fact_checking', '8 de maio de 2026'),
  ('Cacau Show distribui prêmios de R$ 5.000 e kits de chocolate no Dia das Mães via questionário digital.', 'provavelmente_falsa', 'Trata-se de um golpe de phishing recorrente em datas comemorativas. A empresa recomenda desconsiderar links externos enviados fora dos perfis verificados da marca.', ARRAY['Questionário digital com prêmio', 'Data comemorativa usada como gancho', 'Link fora dos canais oficiais']::text[], ARRAY['Confira promoções apenas no site ou app oficial da Cacau Show', 'Verifique o selo de conta verificada nas redes sociais', 'Não preencha questionários recebidos por link de terceiros']::text[], 'Boatos.org', 'https://www.boatos.org/tecnologia/cacau-show-esta-dando-r-5000-de-presente-de-dia-das-maes.html', 'fact_checking', '5 de maio de 2026'),
  ('O site Gmail Premia libera saques de até R$ 2.500 via Pix para quem pagar taxa de validação.', 'provavelmente_falsa', 'O Google não possui serviços de recompensas com depósitos em dinheiro via Pix. O site fraudulento retém os valores cobrados sob pretexto de "taxa de verificação".', ARRAY['Cobrança de taxa para liberar prêmio', 'Uso indevido da marca Google/Gmail', 'Promessa de saque em dinheiro']::text[], ARRAY['O Google não pede pagamento para liberar prêmios', 'Consulte a central de ajuda oficial do Google', 'Desconfie de qualquer taxa cobrada antecipadamente para "liberar" dinheiro']::text[], 'Boatos.org', 'https://www.boatos.org/tecnologia/gmail-premia-permite-que-voce-realize-saque-de-premio-via-pix.html', 'fact_checking', '12 de agosto de 2026'),
  ('Vídeos enviados pelo WhatsApp contendo a palavra Hiperlog carregam vírus que apagam o celular.', 'provavelmente_falsa', 'Especialistas em segurança cibernética não identificaram nenhum vetor de contaminação sob essa designação. O texto é uma corrente enganosa sem fundamento técnico.', ARRAY['Alerta em corrente sem fonte técnica', 'Nome de vírus genérico e não documentado', 'Pedido de repasse a todos os contatos']::text[], ARRAY['Consulte o CERT.br para alertas reais de segurança', 'Não repasse correntes de alerta sem confirmar a fonte', 'Mantenha o WhatsApp e o sistema operacional atualizados']::text[], 'Boatos.org', 'https://www.boatos.org/tecnologia/alerta-que-aponta-que-golpistas-estao-enviando-videos-com-a-palavra-hiperlog-para-roubar-dados-no-whatsapp-nao-procede.html', 'fact_checking', '8 de maio de 2026'),
  ('O Governo Federal aprovou regras para cobrar IPVA de cadeiras de rodas e bicicletas.', 'provavelmente_falsa', 'O IPVA é um tributo de competência estadual e recai exclusivamente sobre veículos automotores. Não há lei federal ou estadual prevendo a incidência de IPVA sobre bicicletas ou equipamentos de acessibilidade.', ARRAY['Confusão sobre competência tributária', 'Ausência de lei ou projeto de lei citado', 'Alegação sobre equipamento de acessibilidade']::text[], ARRAY['Consulte a legislação tributária do seu estado', 'Verifique comunicados oficiais da Secretaria da Fazenda estadual', 'Desconfie de alegações fiscais sem citação de lei específica']::text[], 'E-farsas', 'https://www.e-farsas.com/o-governo-federal-vai-cobrar-ipva-de-cadeira-de-rodas.html', 'fact_checking', '27 de novembro de 2025'),
  ('Mensagens com o link r/go do Banco Central realizam a liberação imediata de Valores a Receber por Pix.', 'provavelmente_falsa', 'O Banco Central adverte que o único endereço oficial para verificação e resgate de valores esquecidos é valoresareceber.bcb.gov.br. O órgão não utiliza SMS ou intermediários para o repasse desses valores.', ARRAY['Link encurtado ou não oficial', 'Promessa de liberação imediata por Pix', 'Uso indevido da marca Banco Central']::text[], ARRAY['Acesse apenas valoresareceber.bcb.gov.br digitado manualmente', 'Não use links recebidos por SMS ou WhatsApp para essa consulta', 'Confira o domínio antes de informar CPF']::text[], 'g1 Fato ou Fake', 'https://g1.globo.com/fato-ou-fake/noticia/2023/03/08/e-fake-que-mensagens-com-link-nao-oficial-permitam-acesso-a-dinheiro-esquecido-veja-o-unico-link-que-vale.ghtml', 'fact_checking', '8 de março de 2023')
